import { useSyncExternalStore } from "react";

// Store tối giản: state nằm NGOÀI React
function createStore(initial) {
  let state = initial;
  const listeners = new Set();
  return {
    getState: () => state,
    setState: (patch) => { state = { ...state, ...patch }; listeners.forEach((l) => l()); },
    subscribe: (l) => { listeners.add(l); return () => listeners.delete(l); },
  };
}

const store = createStore({ count: 0, theme: "light" });

// Hook chọn một phần state; chỉ render lại khi phần đó đổi
function useStore(selector) {
  return useSyncExternalStore(store.subscribe, () => selector(store.getState()));
}

function Counter() {
  const count = useStore((s) => s.count);
  return <button id="inc" onClick={() => store.setState({ count: store.getState().count + 1 })}>Đếm: {count}</button>;
}
function Total() {
  const count = useStore((s) => s.count);
  return <p id="total">Tổng: {count}</p>;
}

export default function App() {
  return <div><Counter /><Total /></div>;
}

