import { useSyncExternalStore } from "react";

const listeners = new Set();
let state = { count: 0 };
const store = {
  getState: () => state,
  setState: (p) => { state = { ...state, ...p }; listeners.forEach((l) => l()); },
  subscribe: (l) => { listeners.add(l); return () => listeners.delete(l); },
};
const useCount = () => useSyncExternalStore(store.subscribe, () => store.getState().count);

export default function App() {
  const count = useCount();
  return (
    <div>
      <button id="inc" onClick={() => store.setState({ count: count + 1 })}>+</button>
      <button id="reset" onClick={() => store.setState({ count: 0 })}>Reset</button>
      <p id="a">{count}</p>
    </div>
  );
}
